}

_choice_ruser() {
    ps -A -o ruser= | gawk 'NF { print $1 }'
}

_choice_tty() {
    ps -A -o tty= | gawk 'NF && $1 != "??" { print $1 }'
}

_choice_user() {
    ps -A -o user= | gawk 'NF { print $1 }'
